// ===============================================================================
// DAEMIND SRE - PARSER CANÔNICO DE NF-E / ERP (BLING, TINY)
// ===============================================================================
const crypto = require('crypto');
const body = $json.body || $json;

const nota = body.notaFiscal || body.notafiscal || body.retorno?.notasfiscais?.[0]?.notafiscal || body;
const contato = nota.contato || nota.destinatario || body.contato || {};

let rawPhone = (contato.celular || contato.fone || contato.telefone || '').toString().replace(/\D/g, '');
if (rawPhone.length >= 10 && rawPhone.length <= 11) {
  rawPhone = '55' + rawPhone;
}

const clienteNome = (contato.nome || 'Cliente').trim();
const clienteEmail = (contato.email || '').trim().toLowerCase();
const clienteDoc = (contato.cnpj || contato.cpf || '').toString().replace(/\D/g, '');

const numeroNota = parseInt(nota.numero || nota.numeroNF || Date.now(), 10);
const serieNota = nota.serie || '1';
const chaveAcesso = (nota.chaveAcesso || nota.chave || '').toString().replace(/\D/g, '');
const linkDanfe = nota.linkDanfe || nota.danfe || '';
const valorNota = parseFloat(nota.valorNota || nota.valor || nota.totalVenda || 0);

const dedupHash = crypto.createHash('sha256').update(`nfe_${chaveAcesso || numeroNota}_${valorNota}`).digest('hex');

return [{
  json: {
    dedup_hash: dedupHash,
    numero_nota: numeroNota,
    serie_nota: serieNota,
    chave_acesso: chaveAcesso,
    link_danfe: linkDanfe,
    valor_nota: valorNota,
    cliente_nome: clienteNome,
    cliente_email: clienteEmail,
    cliente_whatsapp: rawPhone,
    cliente_doc: clienteDoc
  }
}];

